// Safeguard marker: INSTAOPS_V2_CONTENT — permanent-ID Google Sheets reporting sync and verified Cloudinary asset destroy.
const item = $input.first().json || {};
const headers = item.headers || {};
const body = item.body || item;
const expected = String($env.N8N_WEBHOOK_SECRET || '');
const provided = String(headers['x-dashboard-secret'] || headers['X-Dashboard-Secret'] || '');

function safeEqual(a, b) {
  if (!a || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const ALLOWLIST = [
  'LIST_POSTS',
  'LIST_MEDIA',
  'CREATE_POST',
  'UPDATE_POST',
  'SCHEDULE_POST',
  'CANCEL_SCHEDULE',
  'ARCHIVE_POST',
  'SYNC_RECORD',
  'DELETE_MEDIA',
  'DELETE_POST'
];

const action = String(body.action || '').trim().toUpperCase();
let error = '';
let httpStatus = 200;
if (!expected || !safeEqual(provided, expected)) {
  error = 'Unauthorized webhook secret.';
  httpStatus = 403;
} else if (!ALLOWLIST.includes(action)) {
  error = `Unsupported action: ${action}`;
  httpStatus = 400;
} else if ((action === 'DELETE_MEDIA' || action === 'DELETE_POST') && body.confirm !== true) {
  error = 'Explicit confirm: true is required for destructive Cloudinary asset removal.';
  httpStatus = 403;
}

return [{
  json: {
    valid: !error,
    error,
    httpStatus,
    action,
    body,
    post_id: String(body.post_id || body.external_id || (body.row && body.row.post_id) || ''),
    entity_uuid: String(body.entity_uuid || body.post_uuid || ''),
    request_id: String(body.request_id || '')
  }
}];

const rows = $('SHEETS | Read Posts Tab').all().map(i => i.json).filter(r => r && r.post_id);
const logs = $input.all().map(i => i.json).filter(l => l && l.log_id);
return [{ json: { ok: true, rows, logs } }];

const assets = $('SHEETS | Read MediaAssets Tab').all().map(i => i.json).filter(a => a && (a.internal_asset_id || a.post_id));
const u = $input.first().json || {};
const storage = u.storage || u.credits ? {
  storageBytesUsed: u.storage?.usage ?? null,
  bandwidthBytesUsed: u.bandwidth?.usage ?? null,
  creditsUsagePercent: u.credits?.used_percent ?? null,
  resourcesCount: u.resources ?? null,
  plan: u.plan || undefined
} : null;
return [{ json: { ok: true, assets, storage } }];

const req = $('CODE | Validate Content & Sync Action').item.json;
const payload = req.body.payload || {};
const row = payload.row || {
  post_id: req.post_id,
  post_uuid: req.entity_uuid,
  status: payload.status || (req.body.operation === 'SOFT_DELETE' ? 'DELETED' : 'DRAFT'),
  deleted_at: payload.deleted_at || '',
  sheets_sync_status: 'SYNCED',
  sheets_synced_at: new Date().toISOString()
};
row.post_uuid = row.post_uuid || req.entity_uuid || '';
row.sheets_sync_status = 'SYNCED';
row.sheets_synced_at = new Date().toISOString();
return [{ json: row }];

const req = $('CODE | Validate Content & Sync Action').item.json;
const b = req.body || {};
const row = b.row || b.record || { post_id: req.post_id, updated_at: new Date().toISOString() };
return [{ json: row }];

function sha1Hex(str) {
  function rotl(n, s) { return (n << s) | (n >>> (32 - s)); }
  const utf8 = unescape(encodeURIComponent(str));
  const words = [];
  for (let i = 0; i < utf8.length; i++) words[i >> 2] = (words[i >> 2] || 0) | ((utf8.charCodeAt(i) & 0xff) << (24 - (i % 4) * 8));
  words[utf8.length >> 2] = (words[utf8.length >> 2] || 0) | (0x80 << (24 - (utf8.length % 4) * 8));
  words[((utf8.length + 8) >> 6 << 4) + 15] = utf8.length * 8;
  let h0 = 0x67452301, h1 = 0xefcdab89, h2 = 0x98badcfe, h3 = 0x10325476, h4 = 0xc3d2e1f0;
  const w = new Array(80);
  for (let i = 0; i < words.length; i += 16) {
    let a = h0, b = h1, c = h2, d = h3, e = h4;
    for (let t = 0; t < 80; t++) {
      w[t] = t < 16 ? (words[i + t] || 0) : rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
      const f = t < 20 ? ((b & c) | ((~b) & d)) + 0x5a827999 : t < 40 ? (b ^ c ^ d) + 0x6ed9eba1 : t < 60 ? ((b & c) | (b & d) | (c & d)) + 0x8f1bbcdc : (b ^ c ^ d) + 0xca62c1d6;
      const temp = (rotl(a, 5) + f + e + w[t]) >>> 0;
      e = d; d = c; c = rotl(b, 30) >>> 0; b = a; a = temp;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0; h4 = (h4 + e) >>> 0;
  }
  return [h0, h1, h2, h3, h4].map(n => n.toString(16).padStart(8, '0')).join('');
}

const req = $('CODE | Validate Content & Sync Action').item.json;
const assetsInput = Array.isArray(req.body.assets) ? req.body.assets : [];
const cloudName = String($env.CLOUDINARY_CLOUD_NAME || 'djkkknb9k');
const apiKey = String($env.CLOUDINARY_API_KEY || '');
const apiSecret = String($env.CLOUDINARY_API_SECRET || '');
const ts = Math.floor(Date.now() / 1000);

if (!assetsInput.length) {
  return [{ json: { skipDestroy: true, internal_asset_id: '', public_id: '', resource_type: 'video', cloud_name: cloudName } }];
}

return assetsInput.map(a => {
  const pubId = String(a.public_id || a.cloudinary_public_id || '');
  const toSign = `invalidate=true&public_id=${pubId}&timestamp=${ts}${apiSecret}`;
  return {
    json: {
      skipDestroy: false,
      internal_asset_id: String(a.internal_asset_id || ''),
      post_id: req.post_id,
      public_id: pubId,
      resource_type: String(a.resource_type || 'video'),
      cloud_name: cloudName,
      api_key: apiKey,
      timestamp: String(ts),
      signature: sha1Hex(toSign)
    }
  };
});

const req = $('CODE | Validate Content & Sync Action').item.json;
const reqAssets = $('CODE | Sign Cloudinary Destroy Requests').all();
const resList = $input.all();
const outcomes = [];
for (let i = 0; i < reqAssets.length; i++) {
  const a = reqAssets[i].json;
  if (a.skipDestroy) continue;
  const r = (resList[i] && resList[i].json) || {};
  outcomes.push({
    internal_asset_id: a.internal_asset_id,
    public_id: a.public_id,
    result: r.result || (r.error ? 'error' : 'unknown'),
    error: r.error ? String(r.error.message || r.error) : ''
  });
}
const nextStatus = req.action === 'DELETE_POST' ? 'DELETED' : 'MEDIA_DELETED';
return [{ json: { ok: true, post_id: req.post_id, status: nextStatus, outcomes } }];
